__attribute__((nonnull(1, 2))) static inline void hecc_encode_impl(const uint8_t *inbuf, uint8_t *outbuf, size_t insize)
{
    uint8_t p1 = 0;
    uint8_t p2 = 0;
    size_t power2 = 4;
    uint8_t data = 0;
    insize *= 8;
    for (size_t i = 3, j = 0; j < insize; i++)
    {
        if (power2 == i)
        {
            power2 *= 2;
            continue;
        }
        if (0 == j % 8)
        {
            *outbuf++ = data = *inbuf++;
            p2 ^= __builtin_parity(data);
        }
        if (data & 1)
        {
            p1 = p1 ^ (uint8_t)i;
        }
        data >>= 1;
        j++;
    }
    p2 ^= __builtin_parity(p1);
    *outbuf = p1 + (p2 << 7);
}

functions.hecc_encode:
__attribute__((nonnull(1, 3, 4))) _Bool hecc_encode(const uint8_t *inbuf, size_t insize, uint8_t *outbuf,
                                                    size_t *outsize)
{
    if (insize > (~(size_t)0 >> 4) * 15)
    {
        *outsize = 0;
        return 0;
    }
    size_t reqsize = insize + 14;
    reqsize /= 15;
    reqsize += insize;
    if (*outsize < reqsize)
    {
        *outsize = reqsize;
        return 0;
    }
    *outsize = 0;
    while (insize >= 15)
    {
        hecc_encode_impl(inbuf, outbuf, 15);
        inbuf += 15;
        insize -= 15;
        outbuf += 16;
        *outsize += 16;
    }
    if (insize)
    {
        uint8_t buf[15] = {0};
        for (size_t i = 0; i < insize; i++)
        {
            buf[i] = inbuf[i];
        }
        hecc_encode_impl(buf, outbuf, insize);
        inbuf += insize;
        outbuf += insize + 1;
        *outsize += insize + 1;
    }
    return 1;
}

functions.log2uint8:
static inline uint8_t log2uint8(uint8_t v)
{
    return 31 - __builtin_clz(v);
}

functions.hecc_decode_impl:
__attribute__((nonnull(1, 2))) static inline _Bool hecc_decode_impl(const uint8_t *inbuf, uint8_t *outbuf,
                                                                    size_t insize)
{
    if (insize < 2)
    {
        return 0;
    }
    uint8_t p1 = 0;
    uint8_t p2 = 0;
    size_t power2 = 4;
    uint8_t data = 0;
    uint8_t check = inbuf[--insize];
    for (size_t i = 0; i < insize; i++)
    {
        outbuf[i] = inbuf[i];
    }
    insize *= 8;
    for (size_t i = 3, j = 0; j < insize; i++)
    {
        if (power2 == i)
        {
            power2 *= 2;
            continue;
        }
        if (0 == j % 8)
        {
            data = *inbuf++;
            p2 ^= __builtin_parity(data);
        }
        if (data & 1)
        {
            p1 = p1 ^ (uint8_t)i;
        }
        data >>= 1;
        j++;
    }
    p1 ^= check & 0x7f;
    if (p1)
    {
        uint8_t pm = check;
        p2 ^= __builtin_parity(pm);
        if (!p2)
        {
            return 0;
        }
        if (0 != (p1 & (p1 - 1)))
        {
            p2 = p1 - log2uint8(p1) - 2;
            pm = p2 / 8;
            p2 = p2 % 8;
            outbuf[pm] ^= 1 << p2;
        }
    }
    return 1;
}

functions.hecc_decode:
__attribute__((nonnull(1, 3, 4))) _Bool hecc_decode(const uint8_t *inbuf, size_t insize, uint8_t *outbuf,
                                                    size_t *outsize)
{
    if (insize % 16 == 1)
    {
        *outsize = 0;
        return 0;
    }
    size_t reqsize = insize / 16;
    reqsize += !!(insize % 16);
    reqsize = insize - reqsize;
    if (*outsize < reqsize)
    {
        *outsize = reqsize;
        return 0;
    }
    *outsize = 0;
    while (insize >= 16)
    {
        if (!hecc_decode_impl(inbuf, outbuf, 16))
        {
            return 0;
        }
        inbuf += 16;
        insize -= 16;
        outbuf += 15;
        *outsize += 15;
    }
    if (insize)
    {
        uint8_t buf[16] = {0};
        if (!hecc_decode_impl(inbuf, buf, insize))
        {
            return 0;
        }
        for (size_t i = 0; i < insize - 1; i++)
        {
            outbuf[i] = buf[i];
        }
        inbuf += insize;
        outbuf += insize - 1;
        *outsize += insize - 1;
    }
    return 1;
}
